INSERT INTO `cn_app_category_built_in` VALUES (1, 'aim', '8', 'collaboration', 'instant-messaging', 1, 'AIM (originally AOL Instant Messenger) is an instant messaging application. The protocol name is OSCAR (Open System for CommunicAtion in Realtime) and is used in both ICQ and AIM services.', 'AOL Instant Messenger (formerly OSCAR)', 'network-protocol', 0, '', '', '2023-06-02 10:12:28', '2023-06-02 10:12:28', 0, 1, 100011);
INSERT INTO `cn_app_category_built_in` VALUES (2, 'amqp', '9', 'business-systems', 'general-business', 1, 'AMQP (Advanced Message Queuing Protocol) is an open standard application layer protocol for message-oriented middleware, originated in 2003 by JP Morgan Chase in London.', 'Advance Message Queuing Protocol', 'client-server', 1, '', '', '2023-06-02 10:12:28', '2023-06-02 10:12:28', 0, 1, 100011);
INSERT INTO `cn_app_category_built_in` VALUES (3, 'arp', '10', 'networking', 'ip-protocol', 1, 'The ARP protocol is used to determine the MAC Address of a PC for which the IP address is known.', 'Address Resolution Protocol', 'network-protocol', 1, '', '', '2023-06-02 10:12:28', '2023-06-02 10:12:28', 0, 1, 100011);
